long long N, M;

void init()
{
	cin >> N >> M;
}

void york()
{
	long long ans = 0;
	for (long long b = 1; b <= N; ++b)
		ans += min(b * b, M) * 2;

	//cout << ans << endl;
	// remove duplicated integer root 
	// integer root's range 
	for (long long r = -2 * N; r <= 2 * N; ++r)
	{
		if (r == 0) continue;
		int moder = ((r % 2) + 2) % 2;

		long long xmin1 = (-2 * N - r);
		long long xmax1= -2 - r;
		long long xmin2;
		long long xmax2;
		if (r > 0)
		{
			xmin2 = 1 / M;
			xmax2 = M / r;
		}
		else
		{
			xmin2 = M / r;
			xmax2 = -1;
		}

		//cout << xmin1 << " " << xmax1 << endl;

		long long xmin = max(xmin1, xmin2);
		long long xmax = min(xmax1, xmax2);
		int xminmoder = ((xmin % 2) + 2) % 2;

		long long app = xmax - xmin + 1;
		if (xminmoder == moder) app++;
		app /= 2;
		if (xmin <= r && r <= xmax) app++;

		//cout << moder << " " << xminmoder << endl;
		//cout << "root = " << r << ", " << xmin << " " << xmax << " app = " << app << endl;

		if (app > 1) ans -= (app - 1);
	}
	cout << ans << endl;
}

int main()
{
	init();
	york();

	return 0;
}

