using namespace std;
const int N = 1010;
int w[N][N], temp[N];
long double f[N][N], g[N][N];
void swap(int &a, int &b)
{
     int temp = a;
     a = b;
     b = temp;
}

void sort1(int d, int l, int r)
{
     int i = l, j = r, mid = w[d][(l + r) / 2];
     while (i <= j)
     {
           while (w[d][i] > mid) i++;
           while (w[d][j] < mid) j--;
           if (i <= j)
           {
                 swap(w[d][i], w[d][j]);
                 i++; j--;
           }
     }
     if (i < r) sort1(d, i, r);
     if (l < j) sort1(d, l, j);
}

void sort2(int l, int r)
{
     int i = l, j = r, mid = temp[(l + r) / 2];
     while (i <= j)
     {
           while (temp[i] > mid) i++;
           while (temp[j] < mid) j--;
           if (i <= j)
           {
                 swap(temp[i], temp[j]);
                 i++; j--;
           }
     }
     if (i < r) sort2(i, r);
     if (l < j) sort2(l, j);
}

long double p(int n, int m)
{
       long double temp = 1;
       for (int i = 1; i <= m; i++)
       temp = temp * i / (n + 1 - i);
       return(temp);
}

int main()
{
    int n, m, sum = 0, i, j, limit, s = 0, k;
    double tmp;
    scanf("%d%d", &n, &m);
    for (i = 1; i <= m; i++)
    {
        scanf("%d", &w[i][0]);
        for (j = 1; j <= w[i][0]; j++)
        {
            scanf("%d", &w[i][j]);
            temp[++sum] = w[i][j];
        }
        sort1(i, 1, w[i][0]);
    }
    sort2(1, sum);
    limit = temp[n];
    i = n;
    while (temp[i] == limit && i > 0) 
    {
          i--;
          s++;
    }
    memset(f, 0, sizeof(f));
    memset(g, 0, sizeof(g));
    f[0][0] = 1.0;
    g[0][0] = 1;
    for (i = 1; i <= m; i++)
    {
        k = 0;
        while (w[i][k + 1] >= limit && k < w[i][0]) k++;
        if (w[i][k] != limit)
        {
            tmp = p(w[i][0], k);
            for (j = 0; j <= s; j++)
            if (g[i - 1][j] != 0)
            {
                f[i][j] += f[i - 1][j] * tmp;
                g[i][j] += g[i - 1][j];
            }
        }
        else
        {
            tmp = p(w[i][0], k);
            for (j = 1; j <= s; j++)
            if (g[i - 1][j - 1] != 0)
            {
                f[i][j] += f[i - 1][j - 1] * tmp;
                g[i][j] += g[i - 1][j - 1];
            } 
            tmp = p(w[i][0], k - 1);
            for (j = 0; j <= s; j++)
            if (g[i - 1][j] != 0)
            {
                f[i][j] += f[i - 1][j] * tmp;
                g[i][j] += g[i - 1][j];
            }
        }
    }
    double ans = double(f[m][s] / g[m][s]);
    printf("%.9f\n", ans);
    return(0);
}

