        r = dy?t/dy+x[i]:1e9;        
        if (t-dy*(mr-x[i])>0&&r<mr) mr=r;
        if (t-dy*(nr-x[i])>0&&r>nr) nr=r;
    }
    mr = floor(mr)-ceil(nr);
    printf ("%.0lf",mr<-1e-14?0.:mr+1.1);
    return 0;
