	N = sc.nextInt();
	D = sc.nextInt();
	vx = new int[N];
	vy = new int[N];
	for (int i = 0; i < N; i++) {
	    vx[i] = sc.nextInt();
	    vy[i] = sc.nextInt();
	}
	dp = new Boolean[2][2][402][402];
	out.println(solve(0, 0, x, y) ? "Anton" : "Dasha");
	out.flush();
	out.close();
    }

    static class MyScanner {

	BufferedReader br;
	StringTokenizer st;

	MyScanner(InputStream is) {
	    br = new BufferedReader(new InputStreamReader(is));
	}

	String next() throws IOException {
	    while (st == null || !st.hasMoreTokens())
		st = new StringTokenizer(br.readLine());
	    return st.nextToken();
	}

	int nextInt() throws IOException {
	    return Integer.parseInt(next());
	}

	long nextLong() throws IOException {
	    return Long.parseLong(next());
	}

	boolean ready() throws IOException {
	    return br.ready();
	}
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.ArrayDeque;
import java.util.Collections;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        final int INF = 0x3f3f3f3f;
        String[] matrix;
        int[][] zoneIndex;
        int zones;
        int[] dx = new int[]{-1, 0, 1, 0};
        int[] dy = new int[]{0, 1, 0, -1};
        int blackNodes;
        List<Integer>[] graph;

        @SuppressWarnings("unchecked")
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            matrix = new String[n];
            for (int i = 0; i < n; ++i)
                matrix[i] = in.next();

            zoneIndex = new int[n][m];
            for (int[] p : zoneIndex) Arrays.fill(p, -1);
            zones = 0;
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (matrix[i].charAt(j) == 'B' && zoneIndex[i][j] == -1) {
                        dfs(i, j);
                        zones++;
                    }
                }
            }
            blackNodes = zones;
            if (zones <= 1) {
                out.println(zones);
                return;
            }
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (matrix[i].charAt(j) == 'W' && zoneIndex[i][j] == -1) {
                        dfs(i, j);
                        zones++;
                    }
                }
            }

            graph = new List[zones];
            for (int i = 0; i < zones; ++i)
                graph[i] = new ArrayList<>();
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    getEdges(i, j);
                }
            }
            for (int i = 0; i < zones; ++i) {
                Collections.sort(graph[i]);
                List<Integer> adj = new ArrayList<>();
                int prev = -1;
                for (int p : graph[i]) {
                    if (p != prev) {
                        adj.add(p);
                        prev = p;
                    }
                }
                graph[i] = adj;
            }

            Queue<Integer> q = new ArrayDeque<>();
            int ans = INF;
            for (int i = 0; i < zones; ++i) {
                int[] dist = new int[zones];
                dist[i] = 1;
                q.add(i);
                int mdist = 1;
                while (!q.isEmpty()) {
                    int node = q.poll();
                    mdist = dist[node];
                    for (int p : graph[node]) {
                        if (dist[p] == 0) {
                            dist[p] = dist[node] + 1;
                            q.add(p);
                        }
                    }
                }
                if (i >= blackNodes) mdist &= ~1;
                else mdist -= (mdist & 1) ^ 1;
                ans = Math.min(ans, mdist);
            }

            out.println(ans);
        }

        private void dfs(int x, int y) {
            zoneIndex[x][y] = zones;
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (0 <= nx && nx < matrix.length &&
                        0 <= ny && ny < matrix[0].length() &&
                        matrix[x].charAt(y) == matrix[nx].charAt(ny) &&
                        zoneIndex[nx][ny] == -1) {
                    dfs(nx, ny);
                }
            }
        }

        private void getEdges(int x, int y) {
            int node = zoneIndex[x][y];
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (!(0 <= nx && nx < matrix.length &&
                        0 <= ny && ny < matrix[0].length())) continue;
                int p = zoneIndex[nx][ny];
                if (p != node) {
                    graph[node].add(p);
                }
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new UnknownError();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

import java.util.*;
import java.io.*;
import java.lang.*;

public final class Solution {

    private final static boolean USE_FILE_IO = false;

    Reader reader;
    Writer writer;

    Solution(Reader reader, Writer writer) {
        this.reader = reader;
        this.writer = writer;
    }

    long solve() throws java.lang.Exception {
        int n = reader.nextInt();
        int[] x = new int[n];
        int[] y = new int[n];
        for (int i=0; i<n; i++) {
            x[i] = reader.nextInt();
            y[i] = reader.nextInt();
        }
        long ans = 0;
        HashMap<Long, Integer> slopes = new HashMap<Long, Integer>();
        HashSet<Line> lines = new HashSet<Line>();
        for (int i=0; i<n-1; i++) {
            for (int j=i+1; j<n; j++) {
                Line line = new Line(x[i], y[i], x[j], y[j]);
                if (lines.add(line)) {
                    ans += (long)lines.size() - 1;
                    long slope = line.getSlope();
                    int count = slopes.getOrDefault(slope, 0);
                    ans -= (long)count;
                    slopes.put(slope, count + 1);    
                }
            }
        }
        return ans;
    }

    class Line {
        int a, b, c;
        Line(int x1, int y1, int x2, int y2) {
            a = y2 - y1;
            b = x1 - x2;
            c = y1 * x2 - y2 * x1;
            if (a < 0 || (a==0 && b < 0)) {
                a = -a;
                b = -b;
                c = -c;
            }
            int gcd = gcd(gcd(Math.abs(a), Math.abs(b)), Math.abs(c));
            a /= gcd;
            b /= gcd;
            c /= gcd;
        }

        long getSlope() {
            return (long)a * 100000L + (long)b;
        }

        @Override
        public int hashCode() {
            return a ^ b ^ c; 
        }

        @Override
        public boolean equals(Object o) {
            if (o == this) return true;
            if (o.getClass() != Line.class) return false;
            Line other = (Line) o;
            return other.a == this.a && other.b == this.b && other.c == this.c;
        }
    }

    static int gcd(int a, int b) {
        if (a == 0) return b;
        return gcd(b % a, a);
    }

    public static void main(String[] args) throws java.lang.Exception {
        Reader reader = null;
        Writer writer = null;
        try {
            if (USE_FILE_IO) {
                reader = new Reader(new FileInputStream("input.txt"));
                writer = new Writer(new FileOutputStream("output.txt"));
            } else {
                reader = new Reader(System.in);
                writer = new Writer(System.out);
            }
            writer.writeLine(new Solution(reader, writer).solve());        
        } finally {
            if (reader != null)
                reader.close();
            if (writer != null)
                writer.close();
        }
    }

    static class Writer {
        BufferedWriter bw;

        public Writer(OutputStream out) {
            bw = new BufferedWriter(new OutputStreamWriter(out));
        }

        void write(String s) throws java.lang.Exception {
            bw.write(s);
        }

        void write(int x) throws java.lang.Exception {
            write(String.valueOf(x));
        }

        void write(long x) throws java.lang.Exception {
            write(String.valueOf(x));
        }

        void write(char c) throws java.lang.Exception {
            bw.write(c);
        }

        void newLine() throws java.lang.Exception {
            bw.newLine();
        }

        void writeLine(String s) throws java.lang.Exception {
            write(s);
            newLine();
        }

        void writeLine(int n) throws java.lang.Exception {
            writeLine(String.valueOf(n));
        }

        void writeLine(long n) throws java.lang.Exception {
            writeLine(String.valueOf(n));
        }

        void writeLine() throws java.lang.Exception {
            writeLine("");
        }

        void close() throws java.lang.Exception {
            bw.flush();
            bw.close();
        }
    }

