            var dp = new long[20];
            dp[1] = 1;
            dp[2] = 1;
            long pow = 10;
            for (int i = 3; i <= 19; i++)
            {
                dp[i] = pow;
                pow *= 10;
            }
            long res = Get(r, dp) - Get(l - 1, dp);
            WriteLine(res);
        }

        private static long Get(long n, long[] dp)
        {
            if (n == 0)
                return 0;
            if (n < 10)
                return n;

            long res = 0;
            var count = 0;
            var initN = n;
            var first = 0L;
            while (n > 0)
            {
                count++;
                first = n;
                n /= 10;
            }
            for (int i = 1; i < count; i++)
            {
                res += 9 * dp[i];
            }
            res += (first - 1) * dp[count];
            n = initN;
            n -= first * (long)Math.Pow(10, count - 1);
            while (n % 10 != first && n > 0)
            {
                n--;
            }
            res += n / 10 + (n != 0 ? 1 : 0);

            return res;
        }

