    dp[1][0] = ModInt::one();
    for d in a.windows(2) {
        let d = d[1] - d[0];
        let mut next = vec![vec![ModInt::zero(); w + 1]; dp.len() + 1];
        // 単体
        for (i, dp) in dp.iter().enumerate() {
            let next = &mut next[i];
            for (j, &v) in dp.iter().enumerate() {
                if let Some(p) = next.get_mut(j + i * d) {
                    *p += v;
                } else {
                    break;
                }
            }
        }
        // 閉じる
        for (i, dp) in dp.iter().enumerate().skip(1) {
            let next = &mut next[i - 1];
            for (j, &v) in dp.iter().enumerate() {
                if let Some(p) = next.get_mut(j + i * d) {
                    *p += ModInt::from(i) * v;
                } else {
                    break;
                }
            }
        }
        // 割り当て
        for (i, dp) in dp.iter().enumerate().skip(1) {
            let next = &mut next[i];
            for (j, &v) in dp.iter().enumerate() {
                if let Some(p) = next.get_mut(j + i * d) {
                    *p += ModInt::from(i) * v;
                } else {
                    break;
                }
            }
        }
        // 開く
        for (i, dp) in dp.iter().enumerate() {
            let next = &mut next[i + 1];
            for (j, &v) in dp.iter().enumerate() {
                if let Some(p) = next.get_mut(j + i * d) {
                    *p += v;
                } else {
                    break;
                }
            }
        }
        dp = next;
    }
    let mut ans = ModInt::zero();
    for a in dp[0].iter() {
        ans += *a;
    }
    println!("{}", ans);
}

