import "fmt"

var (
	n           int
	num         []int64
	par         []int
	rem         []int64
	minCount    int = 1e9
	delimsCache     = make(map[int64]int)
)

func countPrimeDelims(n int64) (count int) {
	if val, ok := delimsCache[n]; ok {
		count = val
		return
	}
	n0 := n
	for ; n%2 == 0; n /= 2 {
		count++
	}
	for p := int64(3); p*p <= n; p += 2 {
		for ; n%p == 0; n /= p {
			count++
		}
	}
	if n > 1 {
		count++
	}
	delimsCache[n0] = count
	return
}

func eval() {
	count := 0
	withPar0 := 0
	for p := 1; p <= n; p++ {
		delimCount := countPrimeDelims(rem[p])
		if delimCount == 1 && num[p] == rem[p] { // rem[p] is prime and p does not have kids
			count += 1
		} else {
			count += delimCount + 1
		}
		if par[p] == 0 {
			withPar0++
		}
	}
	if withPar0 > 1 {
		count++
	}
	if count < minCount {
		minCount = count
	}
}

func brute(i int) {
	if i == n+1 {
		eval()
		return
	}
	par[i] = 0
	brute(i + 1)

	for p := 1; p <= n; p++ {
		if p != i && num[i] <= rem[p] && rem[p]%num[i] == 0 {
			par[i] = p
			rem[p] /= num[i]
			brute(i + 1)
			rem[p] *= num[i]
		}
	}
}

