	num = make([]int64, n+1)
	par = make([]int, n+1)
	rem = make([]int64, n+1)
	for i := 1; i <= n; i++ {
		fmt.Scan(&num[i])
		rem[i] = num[i]
	}
	brute(1)
	fmt.Println(minCount)
}

