public class Solver
{
    public int BitCount(int x)
    {
        int ret = 0;
        while (x > 0)
        {
            ret++;
            x &= x - 1;
        }
        return ret;
    }

    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var p = ReadDoubleArray();

        int z = p.Count(pp => pp == 0);
        m = Math.Min(n - z, m);

        var dp = new double[1 << n];
        var ans = new double[n];
        dp[0] = 1;
        for (int mask = 0; mask < 1 << n; mask++)
            if (BitCount(mask) >= m)
            {
                if (BitCount(mask) == m)
                {
                    for (int i = 0; i < n; i++)
                        if ((mask >> i & 1) == 1)
                            ans[i] += dp[mask];
                }
                continue;
            }
            else
            {
                double s = 0;
                for (int i = 0; i < n; i++)
                    if ((mask >> i & 1) == 0)
                        s += p[i];
                if (s > 0)
                    for (int i = 0; i < n; i++)
                        if ((mask >> i & 1) == 0)
                            dp[mask | 1 << i] += dp[mask] * p[i] / s;
            }

        WriteArray(ans.Select(v => v.ToString(CultureInfo.InvariantCulture)));
    }

