fun main(args: Array<String>) {
    val sc = BufferedReader(InputStreamReader(System.`in`))
    val out = PrintWriter(BufferedOutputStream(System.out))
    val (n, m) = sc.readLine()!!.split(" ").map(String::toInt)
    val maxm = 1 shl n
    val graph = Array(n) { Array(n) { false } }
    val dp = Array(maxm) { Array(n) { 0L } }

    fun first(num: Int): Int {
        var i = 0
        while ((num and (1 shl i++)) == 0){}
        return i-1
    }

    for (i in 0 until m) {
        val (from, to) = sc.readLine()!!.split(" ").map { it.toInt() - 1 }
        graph[from][to] = true
        graph[to][from] = true
    }

    for(mask in 1 until maxm) {
        for(i in 0 until n) {
            val eI = (mask and (1 shl i)) > 0
            val bk = Integer.bitCount(mask)
            if(bk == 1 && eI) {
                dp[mask][i] = 1
            } else if(bk > 1 && eI && first(mask) != i) {
                var sum = 0L
                for(j in 0 until n) {
                    if(graph[i][j]) sum += dp[mask xor (1 shl i)][j]
                }
                dp[mask][i] = sum
            }
        }
    }

    var count = 0L
    for (mask in 7 until maxm) {
        for(i in 0 until n) {
            if (Integer.bitCount(mask) >= 3 && graph[first(mask)][i]) {
                count += dp[mask][i]
            }
        }
    }

    out.println(count / 2)
    out.close()
}

