import (
	"fmt"
	"math"
)

func main() {
	var n int
	fmt.Scan(&n)

	points := make([][2]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&points[i][0], &points[i][1])
	}

	// Calculate the total area
	totalArea := 0.0
	for i := 0; i < n; i++ {
		j := (i + 1) % n
		totalArea += float64(points[i][0]*points[j][1] - points[j][0]*points[i][1])
	}
	totalArea = math.Abs(totalArea) / 2.0

	// Calculate the sum of squares of distances from the origin to each point
	sumSquareDistances := 0.0
	for _, point := range points {
		sumSquareDistances += float64(point[0]*point[0] + point[1]*point[1])
	}

	// Calculate the expected area
	expectedArea := totalArea / sumSquareDistances

	fmt.Printf("%.10f\n", expectedArea)
}

function cutArea(h, w) {
    let min = Math.min(h, w);
    let max = Math.max(h, w);
    let power = Math.floor(Math.log2(min));
    let minCut = Math.pow(2, power);
    let maxCut = Math.min(max, Math.floor(minCut * 1.25));
    if (maxCut / minCut < 0.8) {
        minCut = Math.floor(maxCut / 1.25);
    }
    return [maxCut, minCut].sort((a, b) => b - a).join(' ');
}

