fn main() {

    use std::io::{self, Read};
    use std::cmp::Ordering;
    use std::collections::{HashMap,HashSet};
    use std::mem;

    let mut buffer = String::new();
    let stdin = io::stdin();
    let mut handle = stdin.lock();

    handle.read_to_string(&mut buffer).unwrap();

    let input_strs = buffer.split_whitespace().take(3).map( |x| x.parse::<i64>().unwrap() ).collect::< Vec<i64> >();

    let n = *input_strs.iter().nth(0).unwrap();

    let mut hs = HashSet::new();
    hs.insert(0);

    let mut dp_count = HashMap::new();

    //dp_count.insert( &0, 1 );

    //strategy: use dp and the number of additional unique values added per round tops off at some point for value denominations of 1, 5, 10, 50
    // so use that value for bigger number of rounds
    for i in 0..13 {
        let mut temp = HashSet::new();
        for j in hs.iter() {
            temp.insert( *j + 1i64 );
            temp.insert( *j + 5i64 );
            temp.insert( *j + 10i64 );
            temp.insert( *j + 50i64 );
        }
        mem::swap( & mut temp, & mut hs );
        let count = hs.len();
        dp_count.insert(i+1, count);
    }

    let ans = if n <= 12 {
        *dp_count.get(&n).expect("dp_count") as i64
    } else {
        let increment = *dp_count.get(&12).unwrap() - *dp_count.get(&11).unwrap();
        *dp_count.get(&12).unwrap() as i64 + (n as i64 - 12i64) * increment as i64
    };
    println!( "{}", ans );
}

