func readNNums(reader *bufio.Reader, n int) []int {
	res := make([]int, n)
	x := 0
	bs, _ := reader.ReadBytes('\n')
	for i := 0; i < n; i++ {
		for x < len(bs) && (bs[x] < '0' || bs[x] > '9') && bs[x] != '-' {
			x++
		}
		x = readInt(bs, x, &res[i])
	}
	return res
}

func solve(price []int, E [][]int) int {
	n := len(price)

	A := make([][]bool, n)
	for i := 0; i < n; i++ {
		A[i] = make([]bool, n)
	}

	for _, e := range E {
		u, v := e[0], e[1]
		u--
		v--
		A[u][v] = true
		A[v][u] = true
	}

	res := -1

	for u := 0; u < n; u++ {
		for v := u + 1; v < n; v++ {
			if A[u][v] {
				for w := 0; w < n; w++ {
					if A[u][w] && A[w][v] {
						if res < 0 || price[u]+price[v]+price[w] < res {
							res = price[u] + price[v] + price[w]
						}
					}
				}
			}
		}
	}

	return res
}

