fn build(s: &[u8], it: &mut usize, graph: &mut Vec<Vec<usize>>, nodes: &mut Vec<usize>, l: usize, r: usize) -> bool {
    if r - l <= 1 {
        return true;
    }
    let m = (l + r) >> 1;
    if !build(s, it, graph, nodes, l, m) {
        return false;
    }
    if !build(s, it, graph, nodes, m, r) {
        return false;
    }
    let mut i = l;
    let mut j = m;
    let mut b = vec![];
    while i < m && j < r {
        if *it == s.len() {
            return false;
        }
        if s[*it] == b'0' {
            graph[nodes[i]].push(nodes[j]);
            b.push(nodes[i]);
            i += 1;
        } else if s[*it] == b'1' {
            graph[nodes[j]].push(nodes[i]);
            b.push(nodes[j]);
            j += 1;
        } else {
            unreachable!();
        }
        *it += 1;
    }
    while i < m {
        b.push(nodes[i]);
        i += 1;
    }
    while j < r {
        b.push(nodes[j]);
        j += 1;
    }
    for (idx, &val) in b.iter().enumerate() {
        nodes[idx + l] = val;
    }
    true
}

