var b map[int]map[int]bool = make(map[int]map[int]bool)

func culc1(x, y int) (ok, end bool, xx, yy int) {
	if m < mm {
		return true, true, 0, 0
	}
	if haveA, have := a[x]; have {
		miny := m + 1
		num := 0
		for ay, _ := range haveA {
			if ay >= mm && ay <= m {
				miny = min(ay, miny)
				num++
			}
		}

		if num+miny != m+1 {
			return false, true, 0, 0
		}

		for i := miny; i <= m; i++ {
			numx := 0
			for ax, _ := range b[i] {
				if ax >= nn && ax <= n {
					numx++
				}
			}
			if numx+nn != n+1 {
				return false, true, 0, 0
			}
		}
		return true, false, x, miny - 1
	}

	return true, false, x, m
}

func culc2(x, y int) (ok, end bool, xx, yy int) {
	if n < nn {
		return true, true, 0, 0
	}

	if haveA, have := b[y]; have {
		minx := n + 1
		numx := 0
		for ax, _ := range haveA {
			if ax >= x && ax <= n {
				minx = min(ax, minx)
				numx++
			}
		}

		if numx+minx != n+1 {
			return false, true, 0, 0
		}

		for i := minx; i <= n; i++ {
			numy := 0
			for ay, _ := range a[i] {
				if ay >= mm && ay <= m {
					numy++
				}
			}
			if numy+mm != m+1 {
				return false, true, 0, 0
			}
		}
		return true, false, minx - 1, y
	}

	return true, false, n, m
}

func culc3(x, y int) (ok, end bool, xx, yy int) {
	if m < mm {
		return true, true, 0, 0
	}

	if haveA, have := a[x]; have {
		maxy := mm - 1
		num := 0
		for ay, _ := range haveA {
			if ay >= mm && ay <= m {
				maxy = max(ay, maxy)
				num++
			}
		}

		if maxy+1 != mm+num {
