}

func (r Matrix) multi(r1 Matrix, m uint64) Matrix {
	res := newMatrix(2, 2)
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			for k := 0; k < 2; k++ {
				res.x[i][j] = (res.x[i][j] + r.x[i][k]*r1.x[k][j]) % m
			}
		}
	}
	return res
}

func (r Matrix) powerMod(a uint64, b uint64) Matrix {
	matrix := newMatrix(2, 2)
	matrix.setValue(0, 0, 1)
	matrix.setValue(0, 1, 1)
	matrix.setValue(1, 0, 1)
	for a > 0 {
		if a%2 == 1 {
			matrix = matrix.multi(r, b)
		}
		r = r.multi(r, b)
		a /= 2
	}
	return matrix
}

