function solve(n, m, a) {
  const h = new Array(m).fill(0);
  let res = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      if (a[i][j]) h[j] = 0;else h[j]++;
    }
    const stack = [];
    for (let j = 0; j <= m; j++) {
      while (stack.length && (j === m || h[stack[stack.length - 1]] > h[j])) {
        var _stack;
        const cur = stack.pop(),
              p = (_stack = stack[stack.length - 1]) !== null && _stack !== void 0 ? _stack : -1;
        if (h[cur]) res = Math.max(res, (j - p - 1) * 2 + h[cur] * 2);
      }
      stack.push(j);
    }
  }
  return res;
}

