function solve(n, edges) {
    const adj = {}
    for (let u = 1; u <= n; u++) {
        adj[u] = {}
    }
    edges.forEach(([a, b]) => {
        adj[a][b] = 1
        adj[b][a] = 1
    })

    const gs = Array(n + 1)
    const vs = []
    let g = 1
    for (let u = 1; u <= n; u++) {
        if (gs[u]) continue
        if (g > 3) return -1
        const temp = [u]
        gs[u] = g
        for (let v = u + 1; v <= n; v++) {
            if (!adj[u][v] && !gs[v]) {
                gs[v] = g
                temp.push(v)
            }
        }
        vs.push(temp)
        g++
    }
// console.log(gs, vs)
    if (vs.length < 3) return -1
    for (let i = 0; i < vs.length; i++) {
        for (let a = 0; a < vs[i].length; a++) {
            const u = vs[i][a]
            for (let j = i + 1; j < vs.length; j++) {
                for (let b = 0; b < vs[j].length; b++) {
                    const v = vs[j][b]
                    if (!adj[u][v]) return -1
                }
            }
        }
    }
    for (let [u, v] of edges) {
        if (gs[u] === gs[v]) return -1
    }
    gs.shift()
    return gs.join(' ')
}

