        val n = int
        val k = int

        val d = ints(n)
        val colors = str(n)

        val red = (0 until n).filter { colors[it] == 'R' }.map { d[it] }.toIntArray()
        val orange = (0 until n).filter { colors[it] == 'O' }.map { d[it] }.toIntArray()
        val white = (0 until n).filter { colors[it] == 'W' }.map { d[it] }.toIntArray()

        if (k < 2 || orange.isEmpty() || (red.isEmpty() && white.isEmpty())) {
            cout .. -1 .. nl
            return@done
        }

        fun compose(a: IntArray, b: IntArray): Int {
            if (a.size + b.size < k || a.isEmpty() || b.isEmpty())
                return -1
            var ia = 1
            var ib = 1
            var res = a[0] + b[0]
            repeat(k - 2) {
                if (ia == a.size)
                    res += b[ib++]
                else if (ib == b.size)
                    res += a[ia++]
                else {
                    if (a[ia] > b[ib])
                        res += a[ia++]
                    else
                        res += b[ib++]
                }
            }
            return res
        }

        red.sortDescending()
        orange.sortDescending()
        white.sortDescending()

        val ans = max(compose(red, orange), compose(white, orange))
        cout .. ans .. nl


    }.cout.flush()
}

