class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val N = ni()
    val A = na(N, -1)
    var mx = 0
    val cycles = mutableMapOf<Int, Int>()

    fun dfs(u: Int): Triple<Int, Int, Int> {
      val path = mutableListOf<Int>()
      val visited = BooleanArray(N)
      var cur = u
      while(!visited[cur]) {
        visited[cur] = true
        path += cur
        cur = A[cur]
      }
      val l = path.indexOf(cur)
      val cycle = path.drop(l)
      return Triple(l, cycle.min()!!, cycle.size)
    }

    for (i in 0 until N) {
      val res = dfs(i)
      mx = max(mx, res.first)
      cycles[res.second] = res.third
    }

    debug{cycles.toString()}

    var lcm = 1L
    for (i in cycles) {
      val g = gcd(lcm, i.value.toLong())
      lcm = lcm * i.value.toLong() / g
    }
    debug{"lcm:$lcm mx:$mx"}
    var ans = lcm
    while(ans < mx) {
      ans += lcm
    }
    out.println(ans)
  }













































