    val p1 = HashVal(random.nextLong(2, HASHMOD))
    val pow1 = HashValArray(n+1)
    pow1[0] = HashVal(1)
    for(i in 1 .. n) pow1[i] = pow1[i-1] * p1

    val pinv1 = p1.inverse()

    val st = SegmentTree(n, Seg.EMPTY, combine@{ a, b ->
        if(b.len == 0) return@combine a
        if(a.len == 0) return@combine b
        var first = a.first
        var last = b.last
        var alen = a.len
        var blen = b.len
        var ha1 = a.hash
        var hb1 = b.hash

        if(a.last && b.first) {
            alen--
            blen--

            ha1--
            ha1 *= pinv1
            hb1 -= pow1[blen]

            if(alen == 0) first = false
            if(blen == 0) last = false
        }

        val hash = ha1 * pow1[blen] + hb1

        Seg(first, last, alen + blen, hash)
    })

    st.build { i ->
        val t = T[i] == '1'
        Seg(t, t, 1, if(t) HashVal(1) else HashVal(0))
    }

    val q = readInt()
