data class Seg(val first: Boolean, val last: Boolean, val len: Int, val hash: HashVal) {
    companion object {
        val EMPTY = Seg(false, false, 0, HashVal(0))
    }
}

class SegmentTree<T>(
    val size: Int,
    val identityValue: T,
    val combiner: (T, T) -> T) {

    /* degenericization helpers
    inline val identityValue: T get() = TODO()
    inline fun combiner(a: T, b: T): T = TODO()
    */

    @Suppress("UNCHECKED_CAST")
    private val array = Array<Any?>(size shl 1) { identityValue } as Array<T>

    inline val lastIndex get() = size - 1
    inline val indices get() = 0 until size
    val asList: List<T> by lazy {
        object : AbstractList<T>() {
            override val size: Int get() = this@SegmentTree.size
            override fun get(index: Int): T = this@SegmentTree[index]
        }
    }

    fun build(generator: (Int) -> T) {
        for(i in 0 until size) {
            array[i + size] = generator(i)
        }
        for(i in size-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** instantiates values from an iterable, O(n) time */
    fun copyFrom(iterable: Iterable<T>) {
        run {
            iterable.forEachIndexed { i, t ->
                if(i > lastIndex) return@run
                array[i + size] = t
            }
        }
        for(i in size-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** Updates a value, O(log n) time */
    operator fun set(index: Int, value: T) {
        require(index in 0 until size)
        var i = index + size
        array[i] = value
        while(true) {
            i = i shr 1
            if(i <= 0) break
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** Gets a value by its index, O(1) time */
    operator fun get(index: Int): T {
        require(index in 0 until size)
        return array[index + size]
    }

    /** gets the result of applying the monoid operation to the values in the index range, O(log n) time */
    operator fun get(start: Int, endExclusive: Int): T {
        var l = maxOf(start, 0) + size
        var r = minOf(endExclusive, size) + size

        // two accumulators to support non-commutative monoids
        var lAcc = identityValue
        var rAcc = identityValue

        while(l < r) {
            if(l and 1 == 1) {
                lAcc = combiner(lAcc, array[l++])
            }
            if(r and 1 == 1) {
                rAcc = combiner(array[--r], rAcc)
            }

            l = l shr 1
            r = r shr 1
        }

        return combiner(lAcc, rAcc)
    }

    operator fun get(range: IntRange) = get(range.first, range.last + 1)
}

/** Converts a semigroup to a monoid by using null as the identity value. */
inline fun <T: Any> nullIdentityCombiner(crossinline combiner: (T, T) -> T): (T?, T?) -> T? = { a, b ->
    when {
        b == null -> a
        a == null -> b
        else -> combiner(a, b)
    }
}

infix fun Long.umod(mod: Long) = (this % mod).let { (it shr Long.SIZE_BITS - 1 and mod) + it }

const val HASHMOD = 1L.shl(61) - 1

inline class HashVal(val int: Long) {
    // normalizes an integer that's within range [-MOD, MOD) without branching
    private inline fun normalize(int: Long) = HashVal((int shr Long.SIZE_BITS - 1 and HASHMOD) + int)

    operator fun plus(other: HashVal) = normalize(int + other.int - HASHMOD)
    operator fun plus(other: Int) = plus(normalize(other.toLong()))
    operator fun inc() = normalize(int + (1 - HASHMOD))

    operator fun minus(other: HashVal) = normalize(int - other.int)
    operator fun minus(other: Int) = minus(normalize(other.toLong()))
    operator fun dec() = normalize(int - 1)
    operator fun unaryMinus() = normalize(-int)

    operator fun times(other: HashVal): HashVal {
        val l1 = int and 0xffff_ffff
        val h1 = int ushr 32
        val l2 = other.int and 0xffff_ffff
        val h2 = other.int ushr 32

        val l = l1 * l2
        val m = l1 * h2 + l2 * h1
        val h = h1 * h2
        var ret = (l and HASHMOD) + (l ushr 61) + (h shl 3) + (m ushr 29) + (m shl 35 ushr 3) + 1
        ret = (ret and HASHMOD) + (ret ushr 61)
        ret = (ret and HASHMOD) + (ret ushr 61)
        return HashVal(ret - 1)
    }

    operator fun times(other: Int) = times(normalize(other.toLong()))

    fun pow(exponent: Long): HashVal {
        var e = if(exponent < 0) {
            require(int != 0L) { "Can't invert/divide by 0" }
            exponent umod HASHMOD - 1
        } else exponent

        var res = HashVal(1)
        var b = this

        while(e > 0) {
            if(e and 1 == 1L) {
                res *= b
            }
            e = e shr 1
            b *= b
        }
        return res
    }

    inline fun inverse() = inv_unmemoized()

    fun inv_unmemoized(): HashVal {
        require(int != 0L) { "Can't invert/divide by 0" }
        return pow(HASHMOD - 2)
    }

    operator fun div(other: HashVal) = times(other.inverse())
    operator fun div(other: Int) = div(normalize(other.toLong()))

    override inline fun toString() = int.toString()
}

inline class HashValArray(val intArray: LongArray): Collection<HashVal> {
    inline operator fun get(i: Int) = HashVal(intArray[i])
    inline operator fun set(i: Int, v: HashVal) { intArray[i] = v.int }

    override inline val size: Int get() = intArray.size
    inline val lastIndex get() = intArray.lastIndex
    inline val indices get() = intArray.indices

    override inline fun contains(element: HashVal): Boolean = element.int in intArray

    override fun containsAll(elements: Collection<HashVal>): Boolean = elements.all(::contains)

    override inline fun isEmpty(): Boolean = intArray.isEmpty()

    override fun iterator(): Iterator<HashVal> = object: Iterator<HashVal> {
        var index = 0
        override fun hasNext(): Boolean = index < size
        override fun next(): HashVal = get(index++)
    }

    fun copyOf(newSize: Int) = HashValArray(intArray.copyOf(newSize))
    fun copyOf() = copyOf(size)
}
