fun isprime(n: Int): Boolean {
    if (n == 2 || n == 3)
        return true
    if (n % 2 == 0 || n % 3 == 0 || n == 1)
        return false
    var i = 5
    var w = 2
    while (i * i <= n) {
        if (n % i == 0)
            return false
        i += w
        w = 6 - w
    }
    return true
}

fun ispalin(n: Int): Boolean {
    val str = n.toString()
    for (i in 0..str.length/2 - 1) {
        if (str[i] != str[str.length - i - 1]) return false
    }
    return true
}

