        self.n4 + self.n7
    }
    fn digit_sum(&self) -> usize{
        self.n4 * 4 + self.n7 * 7
    }
    fn less_than(&self, other: &LuckyNum) -> bool{
        if self.len() < other.len(){
            true
        }
        else if self.len() > other.len(){
            false
        }
        else{
            self.n4 > other.n4
        }
    }
