class Line
{
    public const ptrdiff_t firstStar;
    public const ptrdiff_t lastStar;
    public const string line;

    this(in string line)
    {
        this.firstStar = std.string.indexOf(line, '*');
        this.lastStar = std.string.lastIndexOf(line, '*');
        this.line = line;
    }

    invariant()
    {
        assert(firstStar <= lastStar, format("Last star cannot be before the first one: %s, %s", firstStar, lastStar));
        assert(firstStar >= 0 || (firstStar == -1 && lastStar == -1), "Both indexes must be -1 or >= 0");
    }
}

void testDotsCount(in string line, in ptrdiff_t firstStar, in ptrdiff_t lastStar)
{
    Line l;
    l = new Line(line);
    assert(l.firstStar == firstStar, format("Bad first star index: expected %s, got %s", firstStar, l.firstStar));
    assert(l.lastStar == lastStar, format("Bad last star index: expected %s, got %s", lastStar, l.lastStar));
}

