fn solve_min(counts: &Vec<usize>) -> usize {
    let mut result = 0;
    let mut ptr = 0;
    while ptr < counts.len() {
        if counts[ptr] == 0 {
            ptr += 1;
            continue;
        }
        ptr += 3;
        result += 1;
    }
    return result;
}

fn solve_max(mut counts: Vec<usize>) -> usize {
    let mut result = 0;
    for i in 0..counts.len() {
        if let Some(v) = counts.get_mut(i.wrapping_sub(1)) {
            if *v != 0 {
                *v -= 1;
                result += 1;
                continue;
            }
        }
        if counts[i] != 0 {
            counts[i] -= 1;
            result += 1;
            continue;
        }
        if let Some(v) = counts.get_mut(i + 1) {
            if *v != 0 {
                *v -= 1;
                result += 1;
                continue;
            }
        }
    }
    return result;
}

fn solve<R: std::io::BufRead, W: std::io::Write>(scanner: &mut Scanner<R>, writer: &mut W) {
    let n: usize = scanner.scan();
    let x: Vec<usize> = (0..n).map(|_| scanner.scan()).collect();
    let mut counts: Vec<usize> = vec![0; n + 2];
    for &x in &x {
        counts[x] += 1;
    }
    let min = solve_min(&counts);
    let max = solve_max(counts);
    writeln!(writer, "{} {}", min, max).unwrap();
}

