          qsSum[h | 1 << j] = qsSum[h] ^ qs[j];
        }
      }
      auto xss = new Mint[][](M - M / 2 + 1, 1 << (M / 2));
      auto ys = new Mint[1 << (M / 2)];
      foreach (h; 0 .. 1 << psLen) {
        xss[popcnt(psSum[h] >> (M / 2))][cast(int)(psSum[h] & ((1L << (M / 2)) - 1))] += 1;
      }
      foreach (h; 0 .. 1 << qsLen) {
        ys[cast(int)(qsSum[h])] += 1;
      }
      
      foreach (e; 0 .. M / 2) {
        foreach (f; 0 .. 1 << (M / 2)) {
          if (!(f & 1 << e)) {
            const tmp = ys[f] - ys[f | 1 << e];
            ys[f] += ys[f | 1 << e];
            ys[f | 1 << e] = tmp;
          }
        }
      }
      const invTwo = Mint(2)^^(-(M / 2));
      auto ans = new Mint[M + 1];
      foreach (s; 0 .. M - M / 2 + 1) {
        foreach (e; 0 .. M / 2) {
          foreach (f; 0 .. 1 << (M / 2)) {
            if (!(f & 1 << e)) {
              const tmp = xss[s][f] - xss[s][f | 1 << e];
              xss[s][f] += xss[s][f | 1 << e];
              xss[s][f | 1 << e] = tmp;
            }
          }
        }
        xss[s][] *= ys[];
        xss[s][] *= invTwo;
        foreach (e; 0 .. M / 2) {
          foreach (f; 0 .. 1 << (M / 2)) {
            if (!(f & 1 << e)) {
              const tmp = xss[s][f] - xss[s][f | 1 << e];
              xss[s][f] += xss[s][f | 1 << e];
              xss[s][f | 1 << e] = tmp;
            }
          }
        }
        foreach (f; 0 .. 1 << (M / 2)) {
          ans[s + popcnt(f)] += xss[s][f];
        }
      }
      
      ans[] *= Mint(2)^^(N - r);
      foreach (s; 0 .. M + 1) {
        if (s > 0) write(" ");
        write(ans[s]);
      }
      writeln();
    }
  } catch (EOFException e) {
  }
}

