long power(long m) {
    if (m == 0) return 1;
    if (m == 1) return x % MOD; 
    auto v = power(m/2);
    if (m % 2 == 0) {
        return (v * v) % MOD;
    } else {
        return (((v * v) % MOD) * x) % MOD;
    }
}

