						{
							modint mult2 = mult;
							if (x == y && xk == yk)
							{
								mult2 *= HALF;
							}
							f[n][k][0] += mult2 *
							    f[x][xk][1] *
							    f[y][yk][1];
						}
					}

					yk = k - xk;
