		sort (a);

		auto f = new int [] [] [] (n + 3, n + 2, k + 1);
		f[1][0][0] = 1;
		foreach (num; 1..n + 2)
		{
			int delta = a[num] - a[num - 1];
			foreach (open; 0..n + 2)
			{
				foreach (total; 0..k + 1)
				{
					int cur = f[num][open][total];
