					    cur);

					// inside or open + close
					add (f[num + 1][open][next],
					    cur * 1L * (open + 1));

					// close
					if (open > 0)
					{
						add (f[num + 1][open - 1]
						    [next], cur * 1L * open);
					}
				}
			}
		}

