sub main {

	my $name_1		= <STDIN>;
	$name_1			=~ s/[\r\n]+$//;
	my $name_2		= <STDIN>;
	$name_2			=~ s/[\r\n]+$//;
	my $string		= <STDIN>;
	$string			=~ s/[\r\n]+$//;

	my $name_1_count	= ( $name_1 =~ tr/[A-Z]+// );
	my $name_2_count	= ( $name_2 =~ tr/[A-Z]+// );
	my $string_count	= ( $string =~ tr/[A-Z]+// );

	if ( ( $name_1_count + $name_2_count ) != $string_count ) {

		print( "NO\n" );

		return 0;
	}

	my $names_char_hash	= {};
	my $names_char_array	= [];
	my $string_char_array	= [];
	my $flat_missing_char	= 0;

	$names_char_array	= [ split( '', $name_1 ), split( '', $name_2 ) ];
	$string_char_array	= [ split( '', $string ) ];

	foreach my $char ( @{ $names_char_array } ) {

		$names_char_hash->{ $char } ||= 0;
		$names_char_hash->{ $char }++;
	}

	foreach my $char ( @{ $string_char_array } ) {

		if ( exists( $names_char_hash->{ $char } ) ) {

			$names_char_hash->{ $char }--;

			if ( $names_char_hash->{ $char } == 0 ) {

				delete( $names_char_hash->{ $char } );
			}

		} else {

			$flat_missing_char = 1;

			last;
		}
	}

	if ( $flat_missing_char ) {

		print( "NO\n" );

		return 0;
	}

	if ( scalar( keys %{ $names_char_hash } ) == 0 ) {

		print( "YES\n" );

		return 0;
	}

	return 0;
}

