procedure qsort(x,l,r:longint);
 var xx,i,j:longint;
 begin
 i:=l; j:=r;
 xx:=tt[x,(l+r) div 2];
 while i<=j do
  begin
  while tt[x,i]<xx do inc(i);
  while tt[x,j]>xx do dec(j);
  if i<=j then
