    x:=x div 10;
    inc(n);
  end;
  kol:=n;
end;
function probeg(x:int64):int64;
Var z,rez:int64;
begin
  rez:=0;
  z:=1;
  while x<>0 do
  begin
    rez:=rez+z*(9-x mod 10);
    x:=x div 10;
    z:=z*10;
  end;
  probeg:=rez;
end;
